sibling_emails = {contact["email"].strip().casefold() for contact in sibling_contacts if contact["email"].strip()}

def transaction_date(transaction):
    created_at = transaction["created_at"].strip()
    date_text = created_at[:10]
    parts = date_text.split("-")
    assert len(parts) == 3 and len(parts[0]) == 4
    year, month, day = [int(part) for part in parts]
    assert 1 <= month <= 12 and 1 <= day <= days_in_month(year, month)
    return f"{year:04d}-{month:02d}-{day:02d}"

like_candidates_by_id = {}
for transaction in feed_transactions:
    participant_emails = {
        transaction["sender"]["email"].strip().casefold(),
        transaction["receiver"]["email"].strip().casefold(),
    }
    if transaction_date(transaction) == yesterday_date and participant_emails.intersection(sibling_emails):
        like_candidates_by_id[transaction["transaction_id"]] = transaction
like_candidates = list(like_candidates_by_id.values())
target_transaction_ids = [transaction["transaction_id"] for transaction in like_candidates]
assert len(target_transaction_ids) == len(set(target_transaction_ids))
before_like_counts = {transaction["transaction_id"]: transaction["like_count"] for transaction in like_candidates}
print({"reviewed_like_candidates": [{"transaction_id": transaction["transaction_id"], "created_at": transaction["created_at"], "sender": transaction["sender"], "receiver": transaction["receiver"], "like_count": transaction["like_count"]} for transaction in like_candidates]})

verified_feed_transactions = []
verification_page_index = 0
while True:
    verification_page = apis.venmo.show_social_feed(access_token=venmo_access_token, page_index=verification_page_index, page_limit=20)
    verified_feed_transactions.extend(verification_page)
    if len(verification_page) < 20:
        break
    verification_page_index += 1
verified_feed_by_id = {transaction["transaction_id"]: transaction for transaction in verified_feed_transactions}
post_match_ids = set()
for transaction in verified_feed_transactions:
    participant_emails = {
        transaction["sender"]["email"].strip().casefold(),
        transaction["receiver"]["email"].strip().casefold(),
    }
    if transaction_date(transaction) == yesterday_date and participant_emails.intersection(sibling_emails):
        post_match_ids.add(transaction["transaction_id"])
assert post_match_ids == set(target_transaction_ids)
verification_records = []
for transaction_id in target_transaction_ids:
    after_record = verified_feed_by_id.get(transaction_id)
    present = after_record is not None
    increased = present and after_record["like_count"] >= before_like_counts[transaction_id] + 1
    verification_records.append({"transaction_id": transaction_id, "present": present, "before_like_count": before_like_counts[transaction_id], "after_like_count": after_record["like_count"] if present else None, "like_count_increased": increased})
assert all(record["present"] and record["like_count_increased"] for record in verification_records)
print({"verification": verification_records, "verified_transaction_count": len(verification_records)})
